 for(unsigned job=0;job<=6;job++){character(&g);g.jobId=job;g.mapId=2;g.zeny=50;merchant_open(&u,&g);u.choice=MS_STORAGE_ROW;merchant_input(&u,&g,2,1);assert(merchant_input(&u,&g,2,1)&&u.mode==MS_STORAGE&&g.zeny==0);cases++;}
 /* Actual controller quantities and both directions conserve stack contents. */
